import pandas as pd, re, numpy as np
df = pd.read_csv("../../data/2026_MCM_Problem_C_Data.csv")
def last_active(r):
    ms=[]
    for c in df.columns:
        m=re.match(r'week(\d+)_judge1_score',c)
        if m and pd.notna(r[c]) and float(r[c])>0: ms.append(int(m.group(1)))
    return max(ms) if ms else 0
df['last_active']=df.apply(last_active,axis=1)
df['elim_week']=df['results'].str.extract(r'Eliminated Week (\d+)').astype(float)
jcols=[c for c in df.columns if '_judge' in c]
wkof={c:int(re.match(r'week(\d+)_',c).group(1)) for c in jcols}
anomalies=[]
for (s,w),g in df.groupby(['season'] if False else None) if False else []: pass
for s in sorted(df['season'].unique()):
    gs=df[df['season']==s]
    maxw=gs['last_active'].max()
    for w in range(1,int(maxw)+1):
        cs=[c for c in jcols if wkof[c]==w]
        active=gs[(gs['last_active']>=w)]
        act_idx=active.index
        na = active[cs].astype(str).eq('N/A').any(axis=1)
        n_el = int(((gs['elim_week']==w)).sum())
        if n_el==0 and w<int(maxw): anomalies.append((s,int(w),'NO_ELIM',len(act_idx)))
        if n_el>2: anomalies.append((s,int(w),f'{n_el}_ELIMS',len(act_idx)))
        if na.any(): anomalies.append((s,int(w),'NA_IN_ACTIVE',len(act_idx)))
print("Anomalies (season, week, type, n_active):")
for a in anomalies: print(a)
wd = df[df['results']=='Withdrew']
print("\nWithdrew:", wd[['celebrity_name','season','last_active']].values.tolist())
fin = df[~df['results'].str.match('Eliminated Week|Withdrew',na=True)]
for s,g in fin.groupby('season'):
    if g['last_active'].nunique()>1:
        print("season",s,":",g[['celebrity_name','placement','results','last_active']].values.tolist())
