import pandas as pd, re, numpy as np
df = pd.read_csv("../../data/2026_MCM_Problem_C_Data.csv")
def last_active(r):
    ms=[]
    for c in df.columns:
        m=re.match(r'week(\d+)_judge1_score',c)
        if m and pd.notna(r[c]) and str(r[c]) not in ('N/A',) and float(r[c])>0: ms.append(int(m.group(1)))
    return max(ms) if ms else 0
df['last_active']=df.apply(last_active,axis=1)
df['elim_week']=df['results'].str.extract(r'Eliminated Week (\d+)').astype(float)
# couples eliminated in finale (= last active week of season)
for s,g in df.groupby('season'):
    fin=g['last_active'].max()
    el_fin = g[(g['elim_week']==fin)]
