# finalists per season
fin_rows = df[~df['results'].str.match('Eliminated Week|Withdrew',na=True)]
print("\nfinalist counts:", fin_rows.groupby('season').size().to_dict())
# placements distribution of finalists
print("\nfinalist results values:", fin_rows['results'].value_counts().to_dict())
# sample scipy
try:
    import scipy; print("\nscipy available:", scipy.__version__)
except ImportError as e: print("no scipy", e)
